async function extractChatMaterial(file: File, progress?: (message: string) => void): Promise<ReadableMaterial> {
  if (!/\.(?:tex|latex)$/i.test(file.name)) return extractMaterial(file, progress);
  if (!file.size || file.size > MAX_FILE_SIZE) throw new Error('Choose a nonempty LaTeX file smaller than 25 MB.');
  const text = new TextDecoder('utf-8', { fatal: true }).decode(await file.arrayBuffer());
  if (text.length > 4_000_000) throw new Error('Split this LaTeX source into smaller files.');
  return { version: 1, name: file.name, kind: 'text', pages: splitTextSections(text), wordCount: text.trim() ? text.trim().split(/\s+/).length : 0 };
}

